def load_data():
    if os.path.exists(DATA_FILE):
        try:
            with open(DATA_FILE, 'r', encoding='utf-8') as f:
                d = json.load(f)
                if not d.get('cover_info', {}).get('hero_img_b64'):
                    d.setdefault('cover_info', {})['hero_img_b64'] = MELO1_DEFAULT
                if not d.get('cover_info', {}).get('bg_img_b64'):
                    d.setdefault('cover_info', {})['bg_img_b64'] = MELO2_DEFAULT
                return d
        except Exception:
            return get_default_data()
    else:
        d = get_default_data()
        save_data(d)
        return d

def save_data(data):
    with open(DATA_FILE, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

def file_to_b64(u):
    if u is None: return None
    try:
        return f"data:{u.type};base64,{base64.b64encode(u.getvalue()).decode('utf-8')}"
    except Exception:
        return None

def get_item_sku(item):
    if isinstance(item, dict):
        if item.get('sku'): return str(item['sku'])
        if item.get('id'): return f"REF-{item['id']}"
        if item.get('name'):
            clean_n = "".join(c for c in str(item['name']).upper() if c.isalnum())
            return f"SKU-{clean_n[:12]}"
    return "SKU-MELO001"

def build_whatsapp_invoice_text(client_name, client_phone, items_list, client_cedula="", client_address="", client_city="", client_payment="", client_notes=""):
    c_name = str(client_name).strip() if client_name and str(client_name).strip() else "Nas Murillo"
    c_phone = str(client_phone).strip() if client_phone and str(client_phone).strip() else "+573028081327"
    cedula = str(client_cedula).strip()
    address = str(client_address).strip()
    city = str(client_city).strip()
    payment = str(client_payment).strip()
    notes = str(client_notes).strip()
    
    lines = []
    lines.append(f"Hola, soy {c_name},")
    lines.append("")
    lines.append("Link a mi pedido: https://melos-beauty-catalogo-uwyau8ttti9kfmhywlvtlc.streamlit.app")
    lines.append("")
    lines.append("DATOS PARA LA FACTURA:")
    lines.append(f"• Nombre: {c_name}")
    if cedula:
        lines.append(f"• Cédula/NIT: {cedula}")
    lines.append(f"• Celular: {c_phone}")
    if address:
        lines.append(f"• Dirección: {address}")
    if city:
        lines.append(f"• Ciudad: {city}")
    if payment:
        lines.append(f"• Método de Pago: {payment}")
    lines.append("")
    lines.append("==============================")
    lines.append("")
    lines.append("quiero hacer este pedido en Melo's beauty :")
    lines.append("")
    
    subtotal = 0
    for it in items_list:
        if not isinstance(it, dict): continue
        p_name = it.get('name', "Producto Melo's Beauty")
        try:
            p_price = int(it.get('price', 0))
        except Exception:
            p_price = 0
        try:
            p_qty = int(it.get('qty', 1))
        except Exception:
            p_qty = 1
            
        p_sku = get_item_sku(it)
        item_total = p_price * p_qty
        subtotal += item_total
        
        price_str = f"{p_price:,.0f}".replace(",", ".")
        lines.append(f"•  {p_qty} *{p_name}* [SKU: {p_sku}] / COP {price_str}")
        
    lines.append("")
    lines.append("==============================")
    lines.append("")
    subtotal_str = f"{subtotal:,.0f}".replace(",", ".")
    lines.append(f"Subtotal: COP {subtotal_str}")
    lines.append(f"TOTAL: COP {subtotal_str}")
    if notes:
        lines.append("")
        lines.append(f"Notas: {notes}")
    
    raw_text = chr(10).join(lines)
    encoded_text = urllib.parse.quote(raw_text)
    return raw_text, encoded_text


